284	    @Override
285	    @Transactional(readOnly = true)
286	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
287	        String householdId = owner.getHouseholdId();
288	        if (householdId == null) {
289	            return false;
290	        }
291	        return ownerRepository.findAll().stream()
292	            .filter(existing -> existing.getId() != null)
293	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
294	    }
295	
296	    /**
297	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
298	     * whitespace to a single space and lower-case the result, so values that differ only in
299	     * letter case or incidental whitespace are treated as equal. Shared by the household
300	     * (last name) and per-city matching rules.
301	     */
302	    private String normalizeForComparison(String value) {
303	        if (value == null) {
304	            return null;
305	        }
306	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
307	    }
308	
309	    @Override
310	    @Transactional(readOnly = true)
311	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
312	        String identityKey = owner.getIdentityKey();
313	        return ownerRepository.findAll().stream()
314	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
315	    }
316	
317	    @Override
318	    @Transactional(readOnly = true)
319	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
320	        String normalizedLastName = normalizeForComparison(owner.getLastName());
321	        String postcode = owner.getPostcode();
322	        if (normalizedLastName == null || postcode == null) {
323	            return null;
324	        }
325	        String telephone = owner.getTelephone();
326	        return ownerRepository.findAll().stream()
327	            .filter(existing -> existing.getId() != null)
328	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName())))
329	            .filter(existing -> postcode.equals(existing.getPostcode()))
330	            .filter(existing -> telephone == null
331	                ? existing.getTelephone() != null
332	                : !telephone.equals(existing.getTelephone()))
333	            .map(Owner::getId)
334	            .min(Integer::compareTo)
335	            .orElse(null);
336	    }
337	
338	    @Override
339	    @Transactional(readOnly = true)
340	    public int countNamesakes(String firstName, String lastName) throws DataAccessException {
341	        if (firstName == null || lastName == null) {
342	            return 0;
343	        }
344	        return (int) ownerRepository.findAll().stream()
345	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
346	                && lastName.equalsIgnoreCase(existing.getLastName()))
347	            .count();
348	    }
349	
350	    @Override
351	    @Transactional(readOnly = true)
352	    public int countOwnersInCity(String city) throws DataAccessException {
353	        String normalized = normalizeForComparison(city);
354	        if (normalized == null) {
355	            return 0;
356	        }
357	        return (int) ownerRepository.findAll().stream()
358	            .filter(existing -> normalized.equals(normalizeForComparison(existing.getCity())))
359	            .count();
360	    }
361	
362	    @Override
363	    @Transactional(readOnly = true)
364	    public int countOwnersRegisteredOn(LocalDate date) throws DataAccessException {
365	        if (date == null) {
366	            return 0;
367	        }
368	        return (int) ownerRepository.findAll().stream()
369	            .filter(existing -> date.equals(existing.getRegistrationDate()))
370	            .count();
371	    }
372	
373	    @Override
374	    @Transactional(readOnly = true)
375	    public Collection<Visit> findVisitsByPetId(int petId) {
376	        return visitRepository.findByPetId(petId);
377	    }
378	
379	    @Override
380	    @Transactional(readOnly = true)
381	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
382	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
383	    }
384	
385	    private <T> T findEntityById(Supplier<T> supplier) {
386	        try {
387	            return supplier.get();
388	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
389	            // Just ignore not found exceptions for Jdbc/Jpa realization
390	            return null;
391	        }
392	    }
393	
394	}
